export const advancedQuestions: Question[] = [
  // CIRCULATION ROUTIÈRE
  {id:'q101',theme:'circulation',prompt:'Un agent règle la circulation alors que le feu est vert. Quelle instruction dois-tu suivre ?',choices:['Le feu vert','Les gestes et instructions de l’agent','La priorité à droite'],answers:[1],explanation:'Les indications d’un agent chargé de régler la circulation priment sur les feux, les panneaux et les règles générales.',rule:'Hiérarchie de la signalisation et des prescriptions des agents.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q102',theme:'circulation',prompt:'Tu arrives à un STOP sans ligne d’arrêt visible. Où dois-tu immobiliser le véhicule ?',choices:['À hauteur du panneau, même si tu bloques la chaussée','À la limite de la chaussée abordée, à l’endroit où la visibilité permet de céder le passage','Au milieu de l’intersection'],answers:[1],explanation:'L’arrêt doit être complet à la limite de la chaussée abordée. Si la visibilité est insuffisante, tu peux avancer prudemment après le premier arrêt pour observer, puis céder le passage.',rule:'Panneau STOP et ligne d’effet de l’arrêt.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q103',theme:'circulation',prompt:'Le feu passe au vert, mais la file devant toi est immobilisée et tu risques de bloquer le carrefour. Que fais-tu ?',choices:['Tu t’engages car le feu est vert','Tu attends de pouvoir dégager complètement l’intersection','Tu klaxonnes pour que les autres avancent'],answers:[1],explanation:'Un feu vert ne permet pas de s’engager si la circulation est telle que tu risques de rester immobilisé dans l’intersection et de gêner les autres flux.',rule:'Ne pas s’engager dans une intersection encombrée.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q104',theme:'circulation',prompt:'À l’entrée d’un carrefour à sens giratoire, un panneau cédez-le-passage est présent. Qui dois-tu laisser passer ?',choices:['Les véhicules déjà engagés sur l’anneau','Les véhicules qui entrent derrière toi','Aucun véhicule si tu signales à gauche'],answers:[0],explanation:'Le panneau cédez-le-passage impose de laisser passer les véhicules circulant déjà sur l’anneau. Le clignotant ne donne jamais la priorité.',rule:'Priorité à l’entrée d’un carrefour à sens giratoire signalé.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q105',theme:'circulation',prompt:'Tu veux tourner à droite et un cycliste circule à ta droite dans la même direction. Quelle est la bonne attitude ?',choices:['Tourner immédiatement, le clignotant suffit','Contrôler l’angle mort et laisser passer le cycliste si sa trajectoire est prioritaire','Accélérer pour passer avant lui'],answers:[1],explanation:'Le cycliste peut continuer tout droit. Contrôle la piste ou bande cyclable et l’angle mort avant de tourner, sans couper sa trajectoire.',rule:'Changement de direction et protection des cyclistes.',difficulty:'Difficile',source:'Pédagogie originale'},
  {id:'q106',theme:'circulation',prompt:'Un feu jaune fixe s’allume alors que tu es encore assez loin pour freiner sans danger. Que fais-tu ?',choices:['Tu accélères pour passer','Tu t’arrêtes avant la ligne d’effet du feu','Tu continues parce que le jaune autorise toujours le passage'],answers:[1],explanation:'Le feu jaune fixe impose l’arrêt, sauf si le conducteur ne peut plus s’arrêter dans des conditions de sécurité suffisantes.',rule:'Article R412-31 du Code de la route.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q107',theme:'circulation',prompt:'Tu circules sur autoroute après avoir terminé un dépassement. Où dois-tu te replacer ?',choices:['Sur la voie la plus à droite disponible, lorsque le rabattement est sûr','Sur la voie du milieu jusqu’à la prochaine sortie','Sur la voie de gauche pour mieux voir'],answers:[0],explanation:'Après un dépassement, on se rabat sur la voie la plus à droite dès que cela peut être fait sans danger. Les voies de gauche servent au dépassement.',rule:'Circulation sur chaussées à plusieurs voies.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q108',theme:'circulation',prompt:'Une flèche au sol indique que ta voie est réservée au mouvement vers la gauche. Tu souhaites aller tout droit. Que dois-tu faire ?',choices:['Suivre la flèche et tourner à gauche','Changer de voie suffisamment tôt si cela est autorisé et sûr','Continuer tout droit en franchissant la ligne'],answers:[1],explanation:'Les flèches de sélection indiquent les directions autorisées depuis chaque voie. Il faut se placer à l’avance, sans couper une ligne interdite ni surprendre les autres.',rule:'Marquage de sélection des voies.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q109',theme:'circulation',prompt:'Tu quittes une propriété privée pour entrer sur une route. Qui doit céder le passage ?',choices:['Les véhicules déjà sur la route','Les véhicules circulant derrière toi uniquement','Le véhicule le plus lent'],answers:[0],explanation:'En débouchant d’un accès privé, d’un chemin de terre ou d’un lieu non ouvert à la circulation générale, tu dois céder le passage aux usagers de la route abordée.',rule:'Règles de priorité en sortie d’accès non ouvert à la circulation générale.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q110',theme:'circulation',prompt:'Tu veux dépasser un véhicule, mais tu ne vois pas la fin de la manœuvre à cause d’un sommet de côte. Que fais-tu ?',choices:['Tu commences le dépassement rapidement','Tu renonces et attends une visibilité suffisante','Tu klaxonnes avant de dépasser'],answers:[1],explanation:'Tu dois disposer d’une visibilité suffisante pour effectuer toute la manœuvre et te rabattre sans danger. Un avertisseur sonore ne rend pas le dépassement sûr.',rule:'Conditions de dépassement et visibilité.',difficulty:'Facile',source:'Pédagogie originale'},

  // LE CONDUCTEUR
  {id:'q111',theme:'conducteur',prompt:'Tu es en période probatoire. Quel seuil d’alcoolémie s’applique en règle générale ?',choices:['0,2 g/L de sang','0,5 g/L de sang','0,8 g/L de sang'],answers:[0],explanation:'Le seuil légal est de 0,2 g/L de sang pour un conducteur en période probatoire. En pratique, la règle la plus sûre est de ne pas consommer d’alcool avant de conduire.',rule:'Alcool au volant : seuil du permis probatoire.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q112',theme:'conducteur',prompt:'Tu as un permis classique et tu envisages de conduire après avoir bu. Quel seuil général ne dois-tu pas atteindre ?',choices:['0,2 g/L de sang','0,5 g/L de sang','1,0 g/L de sang'],answers:[1],explanation:'Pour un conducteur soumis au seuil général, il est interdit de conduire à partir de 0,5 g/L de sang. Le ressenti personnel ne permet pas de mesurer son alcoolémie.',rule:'Alcool au volant : seuil général.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q113',theme:'conducteur',prompt:'Après avoir consommé du cannabis, même si tu te sens en état de conduire, que dois-tu faire ?',choices:['Conduire lentement','Ne pas conduire','Attendre quelques minutes puis repartir'],answers:[1],explanation:'La conduite après usage de stupéfiants est interdite. Le ressenti et le délai écoulé ne permettent pas de garantir l’absence de risque ou de présence détectable.',rule:'Interdiction de conduire après usage de stupéfiants.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q114',theme:'conducteur',prompt:'Sur autoroute, tu bâilles régulièrement et tu as du mal à garder une trajectoire constante. Quelle est la meilleure décision ?',choices:['Augmenter le volume de la radio','T’arrêter dans un endroit sûr pour te reposer','Ouvrir la fenêtre et continuer'],answers:[1],explanation:'Ce sont des signes de somnolence. La seule réponse fiable est de s’arrêter dans un lieu sûr et de se reposer. La musique et l’air frais ne remplacent pas le sommeil.',rule:'Prévention de la somnolence au volant.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q115',theme:'conducteur',prompt:'Tu es immobilisé à un feu rouge dans une file de circulation. Peux-tu prendre ton téléphone en main pour lire un message ?',choices:['Oui, puisque les roues sont arrêtées','Non, tu dois attendre d’être stationné dans un lieu autorisé','Oui, si le message est très court'],answers:[1],explanation:'Un arrêt temporaire dans la circulation ne constitue pas un stationnement autorisant la manipulation du téléphone. Attends d’être garé dans un lieu où l’arrêt ou le stationnement est autorisé.',rule:'Téléphone tenu en main et véhicule en circulation.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q116',theme:'conducteur',prompt:'En conduisant, le port d’une oreillette permettant d’écouter de la musique est-il autorisé ?',choices:['Oui, si le volume est faible','Non, sauf exceptions prévues pour les appareils correcteurs de surdité','Oui, sur autoroute uniquement'],answers:[1],explanation:'Le port à l’oreille d’un dispositif émettant du son est interdit en circulation, sauf exceptions légales, notamment certains appareils correcteurs de surdité.',rule:'Dispositifs sonores portés à l’oreille.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q117',theme:'conducteur',prompt:'Un médicament porte un pictogramme indiquant un risque important pour la conduite. Que dois-tu faire ?',choices:['Lire la notice et demander conseil à un professionnel de santé avant de conduire','Conduire si tu connais déjà le médicament','Doubler la dose pour t’habituer'],answers:[0],explanation:'Le pictogramme alerte sur un risque de somnolence ou d’altération des capacités. Respecte les indications de la notice et demande conseil à ton médecin ou pharmacien.',rule:'Médicaments et aptitude à la conduite.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q118',theme:'conducteur',prompt:'Tu suis un véhicule et tu détournes les yeux pendant deux secondes. Quel est le principal danger ?',choices:['Tu continues à parcourir une distance importante sans analyser la route','Le véhicule devant toi ralentit automatiquement','La distance de freinage devient nulle'],answers:[0],explanation:'À vitesse routière, deux secondes représentent une distance importante parcourue sans observation efficace. Une distraction augmente le risque de ne pas détecter un danger à temps.',rule:'Temps de réaction et distraction.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q119',theme:'conducteur',prompt:'Un autre automobiliste te provoque et te suit de très près. Quelle attitude est la plus sûre ?',choices:['Freiner brusquement pour lui faire peur','Garder ton calme, éviter l’escalade et lui permettre de dépasser si c’est sûr','Accélérer au-delà de la limite'],answers:[1],explanation:'Une réaction agressive augmente le danger. Garde une conduite régulière, laisse de l’espace et évite toute confrontation.',rule:'Comportement responsable et prévention des risques.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q120',theme:'conducteur',prompt:'Avant un long trajet, tu as très peu dormi. Que vaut-il mieux faire ?',choices:['Reporter le départ ou dormir suffisamment','Boire plusieurs cafés puis partir sans pause','Rouler plus vite pour arriver plus tôt'],answers:[0],explanation:'Le manque de sommeil dégrade la vigilance. Le café peut masquer temporairement la fatigue mais ne remplace pas le repos.',rule:'Sommeil et vigilance du conducteur.',difficulty:'Facile',source:'Pédagogie originale'},

  // LA ROUTE ET SES CONDITIONS
  {id:'q121',theme:'route',prompt:'La visibilité est inférieure à 50 mètres sur autoroute. Quelle vitesse maximale s’applique ?',choices:['130 km/h','110 km/h','50 km/h'],answers:[2],explanation:'Lorsque la visibilité est inférieure à 50 mètres, la vitesse maximale est de 50 km/h sur tous les réseaux, y compris l’autoroute.',rule:'Limitations de vitesse par visibilité réduite.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q122',theme:'route',prompt:'Tu circules sur autoroute sous une pluie importante. Quel est le plafond général de vitesse pour une voiture, hors signalisation plus restrictive ?',choices:['130 km/h','110 km/h','90 km/h'],answers:[1],explanation:'Sur autoroute, le plafond général est abaissé à 110 km/h par temps de pluie ou autres précipitations. Il faut réduire davantage si les conditions l’exigent.',rule:'Limitations de vitesse en cas de précipitations.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q123',theme:'route',prompt:'Sur une route à double sens sans séparateur central, quelle est la limitation générale hors agglomération, sauf décision ou signalisation différente ?',choices:['80 km/h','110 km/h','130 km/h'],answers:[0],explanation:'La limitation générale est de 80 km/h. Certaines sections peuvent être relevées à 90 km/h par décision de l’autorité compétente ; la signalisation locale doit toujours être lue.',rule:'Limitations générales hors agglomération.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q124',theme:'route',prompt:'Tu as un permis probatoire et tu roules sur autoroute lorsque la limite générale est de 130 km/h. Quel est ton plafond ?',choices:['130 km/h','120 km/h','110 km/h'],answers:[2],explanation:'Le conducteur en période probatoire ne doit pas dépasser 110 km/h sur autoroute lorsque la limite générale est de 130 km/h.',rule:'Limitations de vitesse des conducteurs novices.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q125',theme:'route',prompt:'Quel repère minimal est recommandé pour la distance de sécurité avec le véhicule qui précède ?',choices:['Une seconde','Deux secondes','Une demi-seconde'],answers:[1],explanation:'Il est recommandé de conserver au moins deux secondes. Cette marge doit être augmentée en cas de pluie, de fatigue ou de conditions difficiles.',rule:'Distance de sécurité.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q126',theme:'route',prompt:'Dans quelle situation le feu de brouillard arrière peut-il être utilisé ?',choices:['Sous une pluie ordinaire','En cas de brouillard ou de chute de neige, dans les conditions prévues','Dès qu’il fait nuit'],answers:[1],explanation:'Le feu de brouillard arrière est très éblouissant. Il doit être réservé aux situations de brouillard ou de chute de neige prévues par la réglementation, et non à la pluie ordinaire.',rule:'Utilisation des feux de brouillard.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q127',theme:'route',prompt:'Tu descends une longue pente. Quelle technique aide à maîtriser la vitesse et à préserver les freins ?',choices:['Utiliser un rapport adapté et le frein moteur','Rester constamment sur la pédale de frein','Couper le moteur'],answers:[0],explanation:'Un rapport adapté et le frein moteur aident à contrôler la vitesse et limitent l’échauffement des freins. Ne coupe jamais le moteur en descente.',rule:'Conduite en déclivité.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q128',theme:'route',prompt:'Ton véhicule commence à aquaplaner. Quelle réaction est la plus adaptée ?',choices:['Donner un grand coup de volant','Relâcher progressivement l’accélérateur et éviter les gestes brusques','Freiner brutalement'],answers:[1],explanation:'L’aquaplanage correspond à une perte de contact suffisante entre le pneu et la chaussée. Garde une trajectoire régulière, relâche progressivement l’accélérateur et évite les réactions brutales.',rule:'Perte d’adhérence sur chaussée mouillée.',difficulty:'Difficile',source:'Pédagogie originale'},
  {id:'q129',theme:'route',prompt:'Ton véhicule tombe en panne sur autoroute. Où dois-tu mettre les occupants si tu peux rejoindre la zone de sécurité ?',choices:['Dans la voiture sur la bande d’arrêt d’urgence','Derrière la glissière de sécurité, loin de la circulation','Sur la voie de droite'],answers:[1],explanation:'La bande d’arrêt d’urgence reste exposée. Les occupants doivent se mettre à l’abri derrière la glissière lorsque cela peut être fait sans traverser les voies.',rule:'Panne sur autoroute : protection des occupants.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q130',theme:'route',prompt:'Tu constates un ralentissement dans un tunnel. Quelle action est interdite ?',choices:['Conserver une distance de sécurité','Allumer les feux de détresse si tu es immobilisé','Faire demi-tour ou reculer'],answers:[2],explanation:'Le demi-tour et la marche arrière sont interdits et extrêmement dangereux dans un tunnel. Respecte les distances, les feux et les consignes.',rule:'Circulation et sécurité dans les tunnels.',difficulty:'Facile',source:'Pédagogie originale'},

  // LES AUTRES USAGERS
  {id:'q131',theme:'usagers',prompt:'Un piéton attend au bord d’un passage et manifeste clairement son intention de traverser. Que dois-tu faire ?',choices:['Accélérer pour passer avant lui','Lui céder le passage et t’arrêter si nécessaire','Klaxonner pour qu’il attende'],answers:[1],explanation:'Le piéton qui manifeste clairement son intention de traverser bénéficie de la priorité prévue par le Code de la route. Anticipe et arrête-toi si nécessaire.',rule:'Priorité due aux piétons : article R415-11.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q132',theme:'usagers',prompt:'Hors agglomération, quelle distance latérale minimale dois-tu laisser en dépassant un cycliste ?',choices:['50 cm','1 m','1,50 m'],answers:[2],explanation:'Hors agglomération, tu dois laisser au moins 1,50 m de distance latérale lors du dépassement d’un cycliste ou d’un piéton.',rule:'Distance latérale de dépassement.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q133',theme:'usagers',prompt:'Tu tournes à droite en ville avec une bande cyclable sur ta droite. Quel contrôle est indispensable ?',choices:['Contrôler l’angle mort droit avant de tourner','Regarder uniquement le rétroviseur intérieur','Klaxonner puis tourner immédiatement'],answers:[0],explanation:'Un cycliste peut circuler à droite et continuer tout droit. Le contrôle de l’angle mort et de la bande cyclable est indispensable avant de tourner.',rule:'Protection des cyclistes et angles morts.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q134',theme:'usagers',prompt:'Avant d’ouvrir ta portière côté circulation, que dois-tu faire ?',choices:['Ouvrir rapidement pour ne pas gêner','Contrôler le rétroviseur et l’angle mort puis ouvrir progressivement','Te fier uniquement au bruit de la circulation'],answers:[1],explanation:'Un cycliste ou un deux-roues peut arriver silencieusement ou être masqué. Contrôle visuellement avant d’ouvrir.',rule:'Ouverture des portières et sécurité des usagers.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q135',theme:'usagers',prompt:'Un poids lourd tourne à droite dans une rue étroite. Où éviter de te placer ?',choices:['À proximité immédiate de son flanc droit ou dans son angle mort','À distance derrière lui','Dans un emplacement d’attente sûr'],answers:[0],explanation:'Le poids lourd peut avoir besoin de place et possède des angles morts importants. Ne te place pas à sa droite et laisse-le manœuvrer.',rule:'Angles morts et trajectoire des poids lourds.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q136',theme:'usagers',prompt:'Un car scolaire est arrêté avec des enfants à proximité. Quelle attitude adopter ?',choices:['Dépasser rapidement sans ralentir','Ralentir fortement, observer les abords et être prêt à s’arrêter','Klaxonner pour avertir les enfants'],answers:[1],explanation:'Un enfant peut surgir devant ou derrière le car. Réduis ta vitesse et prépare-toi à t’arrêter.',rule:'Vigilance à proximité des transports scolaires.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q137',theme:'usagers',prompt:'Un véhicule prioritaire approche avec ses avertisseurs spéciaux. Que dois-tu faire ?',choices:['Faciliter son passage sans créer un danger','Le suivre pour gagner du temps','Franchir un feu rouge sans contrôler'],answers:[0],explanation:'Tu dois faciliter le passage du véhicule prioritaire, mais sans provoquer un suraccident ni commettre une manœuvre dangereuse.',rule:'Facilités de passage des véhicules d’intérêt général prioritaires.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q138',theme:'usagers',prompt:'À l’approche d’un passage piéton masqué par un véhicule stationné, que dois-tu faire ?',choices:['Maintenir ta vitesse','Ralentir et te préparer à t’arrêter','Te déporter brusquement sur la voie opposée'],answers:[1],explanation:'Un piéton peut être masqué par le véhicule stationné. Ralentis, observe les abords et conserve la capacité de t’arrêter.',rule:'Anticipation des usagers vulnérables.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q139',theme:'usagers',prompt:'Un animal apparaît soudainement sur la chaussée. Quelle réaction est généralement la plus prudente ?',choices:['Faire un écart violent sans regarder','Freiner de manière maîtrisée et conserver le contrôle de la trajectoire','Accélérer pour le dépasser'],answers:[1],explanation:'Un écart brutal peut provoquer une collision avec un véhicule arrivant en sens inverse ou une sortie de route. Freine de façon maîtrisée et conserve le contrôle.',rule:'Évitement des obstacles et maîtrise du véhicule.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q140',theme:'usagers',prompt:'Tu croises un cycliste sur une route étroite. Tu ne peux pas respecter la distance latérale de dépassement. Que fais-tu ?',choices:['Tu dépasses quand même à faible vitesse','Tu attends une zone où le dépassement peut être effectué avec la distance réglementaire','Tu klaxonnes pour qu’il se serre'],answers:[1],explanation:'Ne dépasse pas si tu ne peux pas laisser la distance latérale nécessaire. Attends un endroit où la manœuvre peut être réalisée sans danger.',rule:'Conditions de dépassement des cyclistes.',difficulty:'Facile',source:'Pédagogie originale'},

  // RÉGLEMENTATION
  {id:'q141',theme:'reglementation',prompt:'Depuis le 1er avril 2024, comment les forces de l’ordre vérifient-elles habituellement l’assurance d’une voiture immatriculée ?',choices:['Avec la vignette verte obligatoire sur le pare-brise','À l’aide du Fichier des véhicules assurés (FVA)','Avec le contrôle technique uniquement'],answers:[1],explanation:'Pour les véhicules immatriculés, la carte verte et le certificat apposé sur le pare-brise ne sont plus délivrés ni exigés comme preuve habituelle depuis le 1er avril 2024. La vérification se fait via le FVA.',rule:'Preuve de l’assurance automobile et Fichier des véhicules assurés.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q142',theme:'reglementation',prompt:'Combien de questions comporte l’épreuve théorique générale et combien de bonnes réponses faut-il au minimum ?',choices:['30 questions et 25 bonnes réponses','40 questions et 35 bonnes réponses','50 questions et 45 bonnes réponses'],answers:[1],explanation:'L’ETG comporte 40 questions. Il faut obtenir au moins 35 bonnes réponses pour réussir.',rule:'Organisation de l’épreuve théorique générale.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q143',theme:'reglementation',prompt:'Avec un permis probatoire, quel capital de points est attribué au départ ?',choices:['6 points','8 points','12 points'],answers:[0],explanation:'Le conducteur en période probatoire commence avec un capital de 6 points. La progression dépend de la filière et de l’absence de retrait de points.',rule:'Permis probatoire et capital de points.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q144',theme:'reglementation',prompt:'À quoi sert le disque A apposé à l’arrière d’un véhicule ?',choices:['À signaler un conducteur novice en période probatoire','À indiquer un véhicule prioritaire','À signaler une voiture automatique'],answers:[0],explanation:'Le signe A signale aux autres usagers un conducteur novice soumis à la réglementation de la période probatoire.',rule:'Signe distinctif du conducteur novice.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q145',theme:'reglementation',prompt:'Tu empruntes un véhicule dont le contrôle technique est dépassé. Que dois-tu vérifier ?',choices:['Que l’assurance suffit à autoriser la circulation','Que le contrôle technique est à jour ou que la situation bénéficie d’une dérogation légale','Que le véhicule démarre correctement'],answers:[1],explanation:'Le véhicule doit respecter les obligations de contrôle technique qui lui sont applicables. Un véhicule qui fonctionne n’est pas automatiquement en règle.',rule:'Obligation de contrôle technique selon la catégorie et l’âge du véhicule.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q146',theme:'reglementation',prompt:'Tu souhaites conduire un véhicule avec remorque. Quel élément doit être vérifié en premier ?',choices:['Uniquement la couleur de la remorque','Les masses autorisées de l’ensemble et la catégorie de permis nécessaire','Seulement la puissance du moteur'],answers:[1],explanation:'Les masses autorisées du véhicule et de l’ensemble attelé déterminent les conditions de conduite et la catégorie de permis ou formation nécessaire.',rule:'Permis B et ensembles avec remorque.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q147',theme:'reglementation',prompt:'Tu entres dans une zone à faibles émissions (ZFE) dans une autre ville. Que dois-tu faire ?',choices:['Supposer que les règles sont identiques partout','Vérifier les règles locales, le périmètre, les horaires et la vignette requise','Ignorer les panneaux si ton véhicule est assuré'],answers:[1],explanation:'Les règles d’accès aux ZFE peuvent varier selon la collectivité, les catégories de véhicules et les horaires. Consulte les informations locales à jour.',rule:'Zones à faibles émissions et restrictions locales.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q148',theme:'reglementation',prompt:'Tu pars en zone montagneuse pendant la période hivernale. Quelle précaution administrative et matérielle prendre ?',choices:['Vérifier si la commune est concernée par l’obligation d’équipements hivernaux et les équipements admis','Emporter uniquement un grattoir','Supposer que les pneus été sont toujours autorisés'],answers:[0],explanation:'Certaines communes de massifs montagneux sont concernées par une obligation d’équipements hivernaux pendant une période définie. Vérifie les communes, les dates et les équipements admis.',rule:'Équipements hivernaux dans certaines communes de montagne.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q149',theme:'reglementation',prompt:'Tu prêtes ta voiture à une personne. Quelle responsabilité importante dois-tu vérifier ?',choices:['Qu’elle possède un permis valide et adapté et qu’elle est autorisée par les conditions d’assurance','Qu’elle a seulement une pièce d’identité','Qu’elle sait conduire une boîte manuelle'],answers:[0],explanation:'Le conducteur doit disposer d’un droit de conduire valide et adapté au véhicule. Le propriétaire doit également vérifier les conditions de son contrat d’assurance.',rule:'Droit de conduire et assurance du véhicule.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q150',theme:'reglementation',prompt:'Une limitation locale à 30 km/h est indiquée alors que la limitation générale de la rue serait de 50 km/h. Quelle limite dois-tu respecter ?',choices:['50 km/h car c’est la règle générale','30 km/h indiqués par la signalisation','La vitesse moyenne des autres véhicules'],answers:[1],explanation:'La signalisation locale peut imposer une limitation inférieure à la règle générale. C’est la limitation indiquée qui s’applique.',rule:'Priorité de la signalisation locale de vitesse.',difficulty:'Facile',source:'Pédagogie originale'},

  // PREMIERS SECOURS
  {id:'q151',theme:'premiers-secours',prompt:'Tu arrives le premier sur un accident. Quelle est la première priorité ?',choices:['Protéger les lieux sans te mettre en danger','Déplacer immédiatement toutes les victimes','Prendre des photos'],answers:[0],explanation:'La première priorité est d’éviter un suraccident et de protéger les personnes. Ne t’expose pas à la circulation ou à un autre danger.',rule:'Conduite à tenir : Protéger, Alerter, Secourir.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q152',theme:'premiers-secours',prompt:'Quel numéro permet d’appeler les secours dans l’Union européenne ?',choices:['112','118','911'],answers:[0],explanation:'Le 112 est le numéro d’urgence européen. En France, d’autres numéros spécialisés existent également, mais le 112 permet de joindre les secours.',rule:'Numéro d’urgence européen.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q153',theme:'premiers-secours',prompt:'Lors de l’appel aux secours, quelles informations sont particulièrement utiles ?',choices:['Le lieu précis, le nombre de victimes et les dangers présents','La marque de ton téléphone','Uniquement ton nom'],answers:[0],explanation:'La localisation, le nombre de victimes, leur état apparent et les risques permettent aux secours d’adapter leur intervention.',rule:'Alerte des services d’urgence.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q154',theme:'premiers-secours',prompt:'Une victime est blessée au dos après un choc et aucun danger immédiat ne menace sa vie. Que dois-tu faire ?',choices:['La déplacer pour la mettre assise','Éviter de la déplacer et attendre les secours en la surveillant','Lui faire marcher quelques pas'],answers:[1],explanation:'Ne déplace pas inutilement une victime, notamment en cas de suspicion de traumatisme du dos ou du cou. Alerte et suis les consignes des secours.',rule:'Protection des victimes et suspicion de traumatisme.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q155',theme:'premiers-secours',prompt:'Un motard accidenté porte encore son casque. Quelle attitude adopter ?',choices:['Retirer le casque systématiquement','Ne pas retirer le casque et suivre les consignes des secours','Le faire se relever'],answers:[1],explanation:'Le retrait du casque peut aggraver une blessure cervicale. N’effectue pas ce geste ; protège, alerte et suis les consignes professionnelles.',rule:'Secours à un motocycliste accidenté.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q156',theme:'premiers-secours',prompt:'Une victime consciente vient d’être accidentée. Que peux-tu lui donner à boire ?',choices:['De l’eau immédiatement','Du café','Rien à boire ou à manger en attendant les secours'],answers:[2],explanation:'Ne donne ni à boire ni à manger à une victime. Elle peut nécessiter une intervention médicale ou présenter des blessures non visibles.',rule:'Surveillance et secours aux victimes.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q157',theme:'premiers-secours',prompt:'Une victime ne répond pas et ne respire pas normalement. Quelle action entreprendre ?',choices:['Attendre sans agir','Faire alerter immédiatement les secours et suivre leurs instructions de réanimation et de défibrillation','Lui donner à boire'],answers:[1],explanation:'Il s’agit d’une urgence vitale. Alerte immédiatement, mets le haut-parleur si possible et suis les instructions concernant la réanimation et le défibrillateur.',rule:'Urgence vitale : alerte, réanimation et défibrillateur.',difficulty:'Difficile',source:'Pédagogie originale'},
  {id:'q158',theme:'premiers-secours',prompt:'Tu es sur autoroute et dois appeler les secours après un accident. Quelle solution est la plus adaptée si elle est accessible sans danger ?',choices:['Marcher sur les voies','Utiliser une borne d’appel d’urgence ou le moyen prévu depuis une zone protégée','Te placer derrière un véhicule sur la voie de circulation'],answers:[1],explanation:'Ne marche jamais sur les voies. Rejoins une zone protégée et utilise une borne d’appel ou le moyen d’alerte prévu.',rule:'Sécurité et alerte sur autoroute.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q159',theme:'premiers-secours',prompt:'Le triangle de présignalisation doit-il être posé à chaque panne, même si cela t’oblige à marcher sur une voie rapide ?',choices:['Oui, toujours','Non, il ne doit pas être mis en place si cela présente un danger pour la personne','Oui, avant de mettre le gilet'],answers:[1],explanation:'La mise en place du triangle ne doit jamais exposer la personne à un danger. La sécurité et la mise à l’abri priment.',rule:'Équipement de présignalisation et sécurité.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q160',theme:'premiers-secours',prompt:'Une personne est en état de choc et très angoissée après un accident. Que peux-tu faire ?',choices:['La rassurer, la protéger du froid et surveiller son état','La faire marcher pour se calmer','Lui donner un médicament sans avis'],answers:[0],explanation:'Reste calme, rassure la victime, protège-la du froid et surveille son état jusqu’à l’arrivée des secours.',rule:'Secourir et surveiller une victime.',difficulty:'Facile',source:'Pédagogie originale'},

  // MÉCANIQUE
  {id:'q161',theme:'mecanique',prompt:'À quel moment la pression des pneus se contrôle-t-elle de préférence ?',choices:['À chaud après une longue autoroute','À froid, selon les valeurs du constructeur','Uniquement après une crevaison'],answers:[1],explanation:'La pression se contrôle de préférence à froid. Les valeurs recommandées figurent dans le manuel ou sur l’étiquette du véhicule.',rule:'Entretien des pneumatiques.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q162',theme:'mecanique',prompt:'Un voyant rouge de pression d’huile s’allume pendant que tu roules. Que fais-tu ?',choices:['Tu continues jusqu’à la prochaine révision','Tu t’arrêtes dès que possible en sécurité et coupes le moteur','Tu accélères pour faire disparaître le voyant'],answers:[1],explanation:'Une pression d’huile insuffisante peut endommager gravement le moteur. Arrête-toi en sécurité et consulte les indications du constructeur.',rule:'Voyants d’alerte et lubrification moteur.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q163',theme:'mecanique',prompt:'Ton moteur surchauffe et tu dois vérifier le liquide de refroidissement. Que ne faut-il surtout pas faire ?',choices:['Attendre le refroidissement','Ouvrir immédiatement le bouchon du circuit chaud et sous pression','Lire la notice du véhicule'],answers:[1],explanation:'Le liquide chaud est sous pression et peut provoquer de graves brûlures. Laisse refroidir et suis les indications du constructeur.',rule:'Système de refroidissement du moteur.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q164',theme:'mecanique',prompt:'Les essuie-glaces laissent un voile et des traces qui gênent ta vision. Que dois-tu faire ?',choices:['Les contrôler et les remplacer si nécessaire','Rouler plus vite pour que l’eau s’évacue','Utiliser uniquement les feux de route'],answers:[0],explanation:'Des balais usés diminuent la visibilité. Contrôle-les et remplace-les si nécessaire ; vérifie aussi le lave-glace et le pare-brise.',rule:'Entretien des équipements de visibilité.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q165',theme:'mecanique',prompt:'Tu ressens des vibrations inhabituelles au freinage. Quelle attitude adopter ?',choices:['Ignorer le problème si le véhicule roule','Faire contrôler rapidement le système de freinage','Désactiver les feux stop'],answers:[1],explanation:'Les vibrations peuvent signaler une anomalie de freinage ou de train roulant. Fais contrôler le véhicule et évite de poursuivre si la sécurité est compromise.',rule:'Entretien et contrôle du freinage.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q166',theme:'mecanique',prompt:'Une usure anormale apparaît sur le bord intérieur des pneus. Que peut-elle indiquer ?',choices:['Un défaut possible de géométrie ou de pression','Une adhérence garantie supérieure','Un bon état du parallélisme dans tous les cas'],answers:[0],explanation:'Une usure irrégulière peut révéler un défaut de pression, de géométrie ou de suspension. Un contrôle professionnel permet d’en déterminer la cause.',rule:'Usure des pneumatiques et géométrie.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q167',theme:'mecanique',prompt:'Un voyant de charge batterie s’allume pendant le trajet. Que peut-il signaler ?',choices:['Un problème possible du circuit de charge','Un niveau de carburant élevé','Un fonctionnement normal des airbags'],answers:[0],explanation:'Le voyant de charge peut signaler un défaut d’alternateur, de courroie ou de circuit électrique. Arrête-toi dans un lieu sûr et fais vérifier le véhicule.',rule:'Batterie et circuit de charge.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q168',theme:'mecanique',prompt:'Avant un long voyage avec plusieurs passagers et des bagages, que dois-tu vérifier ?',choices:['La pression des pneus adaptée au chargement','Uniquement la couleur de la carrosserie','La pression à une valeur inférieure pour plus de confort'],answers:[0],explanation:'La pression recommandée peut différer selon la charge. Consulte les valeurs du constructeur et vérifie les pneus à froid.',rule:'Préparation du véhicule et chargement.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q169',theme:'mecanique',prompt:'Un feu stop ne fonctionne plus. Quelle conséquence principale cela présente-t-il ?',choices:['Les conducteurs derrière peuvent ne pas percevoir ton freinage','La distance de freinage diminue','Le moteur consomme forcément moins'],answers:[0],explanation:'Les feux stop préviennent les usagers qui suivent que tu ralentis. Une défaillance réduit la communication et doit être réparée rapidement.',rule:'Éclairage et signalisation du véhicule.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q170',theme:'mecanique',prompt:'Le véhicule tire fortement d’un côté et la direction semble anormale. Que dois-tu faire ?',choices:['Faire contrôler le véhicule et éviter de poursuivre si la maîtrise est compromise','Lâcher le volant pour vérifier','Augmenter la vitesse'],answers:[0],explanation:'Une anomalie de direction, de pneus ou de suspension peut provoquer une perte de contrôle. Ralentis, arrête-toi en sécurité et fais vérifier le véhicule.',rule:'Direction, suspension et tenue de route.',difficulty:'Moyen',source:'Pédagogie originale'},

  // SÉCURITÉ DU VÉHICULE
  {id:'q171',theme:'securite',prompt:'Un passager arrière te dit qu’il n’a pas besoin de ceinture pour un court trajet. Que réponds-tu ?',choices:['La ceinture est obligatoire pour les passagers concernés, même sur un court trajet','La ceinture n’est obligatoire que sur autoroute','Il peut tenir la poignée de toit à la place'],answers:[0],explanation:'La ceinture doit être portée à l’avant comme à l’arrière, même pour un trajet court, sous réserve des dérogations prévues par la loi.',rule:'Port de la ceinture : article R412-1.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q172',theme:'securite',prompt:'Tu installes un siège enfant dos à la route à l’avant. Quelle précaution essentielle dois-tu prendre ?',choices:['Désactiver l’airbag frontal passager selon les instructions du véhicule','Avancer le siège au maximum sans vérifier','Laisser l’airbag actif pour protéger l’enfant'],answers:[0],explanation:'L’airbag frontal passager doit être désactivé lorsqu’un siège dos à la route est installé à l’avant, selon les instructions du véhicule et du siège.',rule:'Sièges enfants et airbag passager.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q173',theme:'securite',prompt:'Comment doit être positionnée une ceinture de sécurité ?',choices:['À plat, sans torsion, correctement sur l’épaule et le bassin','Sous le bras','Derrière le dos'],answers:[0],explanation:'La ceinture doit être à plat et correctement positionnée sur les zones prévues pour retenir le corps. Elle ne doit pas être vrillée ni placée sous le bras.',rule:'Réglage et port de la ceinture.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q174',theme:'securite',prompt:'Tu transportes une valise lourde non arrimée dans l’habitacle. Quel est le risque en cas de freinage ?',choices:['Elle peut devenir un projectile et blesser les occupants','Elle reste immobile grâce à son poids','Elle améliore la stabilité du véhicule'],answers:[0],explanation:'Un objet libre peut être projeté vers les occupants lors d’un freinage ou d’un choc. Place-le dans le coffre et arrime-le si nécessaire.',rule:'Arrimage des objets transportés.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q175',theme:'securite',prompt:'À quoi sert principalement l’ABS lors d’un freinage appuyé ?',choices:['À aider à éviter le blocage des roues et à conserver la capacité de diriger','À garantir un arrêt plus court dans toutes les conditions','À remplacer la ceinture de sécurité'],answers:[0],explanation:'L’ABS limite le blocage des roues lors d’un freinage fort et aide à conserver la capacité de diriger. Il ne garantit pas une distance d’arrêt plus courte sur toutes les surfaces.',rule:'Systèmes de sécurité active : ABS.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q176',theme:'securite',prompt:'L’ESP se déclenche sur une chaussée glissante. Que dois-tu comprendre ?',choices:['Le système aide à stabiliser le véhicule, mais il faut rester prudent','Le véhicule ne peut plus déraper','Tu peux accélérer davantage'],answers:[0],explanation:'L’ESP peut aider à corriger certaines pertes de stabilité, mais il ne supprime pas les limites d’adhérence. Réduis les actions brusques et adapte ta vitesse.',rule:'Systèmes d’aide à la stabilité.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q177',theme:'securite',prompt:'Pourquoi faut-il régler l’appuie-tête correctement ?',choices:['Pour limiter le risque de blessure cervicale lors d’un choc','Pour mieux voir les panneaux','Pour réduire la consommation'],answers:[0],explanation:'Un appuie-tête bien réglé limite le mouvement brusque de la tête et peut réduire le risque de traumatisme cervical, notamment lors d’un choc arrière.',rule:'Réglage des équipements de retenue.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q178',theme:'securite',prompt:'Tu transportes un chargement qui masque partiellement les feux arrière. Que dois-tu faire ?',choices:['Le laisser ainsi si le trajet est court','Repositionner ou signaler le chargement pour que les feux restent visibles et respecter les règles de dimensions','Allumer les feux de détresse en permanence'],answers:[1],explanation:'Le chargement ne doit pas masquer les feux, la plaque ou compromettre la visibilité. Il doit être correctement arrimé et signalé lorsque la réglementation l’exige.',rule:'Transport et signalisation des chargements.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q179',theme:'securite',prompt:'Une caméra de recul ne détecte pas un piéton derrière le véhicule. Quelle règle reste valable ?',choices:['Tu dois effectuer les contrôles visuels et manœuvrer lentement','La caméra remplace totalement les contrôles','Tu peux accélérer puisque l’écran est allumé'],answers:[0],explanation:'Les aides à la manœuvre peuvent être limitées ou ne pas détecter un obstacle. Le conducteur reste responsable de l’observation et de la maîtrise du véhicule.',rule:'Limites des aides à la conduite.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q180',theme:'securite',prompt:'Pourquoi faut-il régler son siège et ses rétroviseurs avant de démarrer ?',choices:['Pour atteindre les commandes et observer correctement sans manipulation en circulation','Pour éviter d’utiliser les clignotants','Pour augmenter la vitesse maximale'],answers:[0],explanation:'Une bonne position permet d’atteindre les commandes, de maîtriser le volant et d’avoir une vision adaptée. Effectue ces réglages avant de prendre la route.',rule:'Installation du conducteur et sécurité.',difficulty:'Facile',source:'Pédagogie originale'},

  // ENVIRONNEMENT
  {id:'q181',theme:'environnement',prompt:'Tu aperçois un feu rouge au loin. Quelle conduite favorise à la fois sécurité et sobriété ?',choices:['Accélérer puis freiner au dernier moment','Anticiper et ralentir progressivement','Passer au point mort et couper le moteur en roulant'],answers:[1],explanation:'L’anticipation permet de ralentir progressivement et d’éviter une accélération suivie d’un freinage inutile.',rule:'Éco-conduite et anticipation.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q182',theme:'environnement',prompt:'Une galerie de toit vide n’est plus nécessaire pour ton trajet. Que vaut-il mieux faire ?',choices:['La retirer si cela est possible','La garder car elle réduit la résistance à l’air','Ajouter des objets pour la stabiliser'],answers:[0],explanation:'Un accessoire extérieur peut augmenter la résistance aérodynamique et la consommation. Retire-le lorsqu’il n’est pas utile.',rule:'Aérodynamisme et consommation.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q183',theme:'environnement',prompt:'Une pression de pneus trop faible peut notamment provoquer…',choices:['Une consommation plus élevée et une usure anormale','Une réduction systématique de la distance de freinage','Une suppression du risque d’aquaplanage'],answers:[0],explanation:'Une pression insuffisante augmente la résistance au roulement, peut provoquer une usure irrégulière et dégrader le comportement du véhicule.',rule:'Entretien des pneumatiques et éco-conduite.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q184',theme:'environnement',prompt:'Tu dois effectuer plusieurs petits déplacements dans le même quartier. Quelle solution peut réduire l’impact environnemental ?',choices:['Regrouper les trajets et choisir un mode adapté','Faire un aller-retour séparé pour chaque objet','Laisser le moteur tourner entre chaque arrêt'],answers:[0],explanation:'Regrouper les déplacements évite les trajets inutiles. Pour de courtes distances, la marche, le vélo ou les transports collectifs peuvent être adaptés.',rule:'Préparation des déplacements et mobilité.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q185',theme:'environnement',prompt:'Tu entres dans une zone à faibles émissions que tu ne connais pas. Quelle attitude est la plus responsable ?',choices:['Vérifier les restrictions locales avant ou pendant la préparation du trajet','Supposer qu’aucune restriction ne s’applique','Masquer ta plaque'],answers:[0],explanation:'Les ZFE dépendent de règles locales pouvant évoluer. Vérifie le périmètre, les horaires, les dérogations et les catégories Crit’Air autorisées.',rule:'Zones à faibles émissions.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q186',theme:'environnement',prompt:'Quel comportement augmente généralement le bruit et la consommation ?',choices:['Des accélérations fortes et des régimes moteur inutilement élevés','Une conduite souple et régulière','Un entretien adapté'],answers:[0],explanation:'Les accélérations brutales et les régimes élevés augmentent généralement la consommation, les émissions et le bruit.',rule:'Éco-conduite.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q187',theme:'environnement',prompt:'Tu laisses ton moteur tourner à l’arrêt pendant une longue attente sans nécessité. Quel est l’effet probable ?',choices:['Une consommation et des émissions inutiles','Une diminution garantie de la pollution','Une recharge systématique de la batterie'],answers:[0],explanation:'Faire tourner inutilement le moteur à l’arrêt consomme du carburant et génère des émissions. Coupe le moteur lors d’un arrêt prolongé lorsque les conditions le permettent.',rule:'Réduction des émissions à l’arrêt.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q188',theme:'environnement',prompt:'Quel est l’intérêt de maintenir une vitesse régulière lorsque les conditions le permettent ?',choices:['Réduire les variations inutiles d’accélération et de freinage','Avoir le droit de dépasser la limitation','Ne plus surveiller la circulation'],answers:[0],explanation:'Une allure régulière évite les variations de vitesse inutiles et améliore souvent la consommation, le confort et la sécurité.',rule:'Conduite souple et régulière.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q189',theme:'environnement',prompt:'Tu as des déchets dans la voiture après un trajet. Que dois-tu faire ?',choices:['Les jeter sur le bas-côté','Les conserver jusqu’à une poubelle adaptée','Les jeter par la fenêtre si personne ne regarde'],answers:[1],explanation:'Les déchets ne doivent jamais être jetés sur la route ou dans la nature. Conserve-les jusqu’à un point de collecte.',rule:'Respect de l’environnement et propreté des voies.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q190',theme:'environnement',prompt:'Quel principe doit toujours primer sur l’éco-conduite ?',choices:['La sécurité et l’adaptation à la circulation','La consommation minimale à tout prix','La vitesse la plus lente possible'],answers:[0],explanation:'L’économie de carburant ne doit jamais compromettre la sécurité, l’adhérence, les distances de sécurité ou la fluidité normale de la circulation.',rule:'Conduite responsable.',difficulty:'Facile',source:'Pédagogie originale'},

  // NOTIONS DIVERSES
  {id:'q191',theme:'divers',prompt:'Une signalisation temporaire de chantier indique une limitation plus basse que d’habitude. Que dois-tu faire ?',choices:['Respecter la limitation temporaire','Garder la limitation habituelle','Respecter uniquement si des ouvriers sont visibles'],answers:[0],explanation:'La signalisation temporaire de chantier doit être respectée même si aucun ouvrier n’est visible au moment du passage.',rule:'Signalisation temporaire des chantiers.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q192',theme:'divers',prompt:'À l’approche d’un passage à niveau, la circulation devant toi est dense. Quand peux-tu t’engager ?',choices:['Dès que le feu est éteint, même si tu risques de rester sur les rails','Uniquement lorsque tu peux franchir entièrement le passage sans t’arrêter dessus','Lorsque le véhicule devant toi commence à avancer, sans autre contrôle'],answers:[1],explanation:'Tu ne dois jamais t’engager si tu risques de rester immobilisé sur la voie ferrée. Attends de pouvoir franchir entièrement le passage.',rule:'Franchissement des passages à niveau.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q193',theme:'divers',prompt:'Une ligne continue sépare les sens de circulation. Que signifie-t-elle en règle générale ?',choices:['Elle ne doit pas être franchie ou chevauchée, sauf exception prévue','Elle peut être franchie si tu mets le clignotant','Elle indique une voie de stationnement'],answers:[0],explanation:'La ligne continue interdit en règle générale son franchissement ou son chevauchement. Des exceptions précises existent, mais elles ne se déduisent pas d’une simple intention de dépasser.',rule:'Marquage longitudinal et lignes continues.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q194',theme:'divers',prompt:'Tu entres dans une zone de rencontre. Quelle attitude adopter ?',choices:['Ralentir fortement, rester attentif aux piétons et respecter le régime de la zone','Rouler à la vitesse habituelle de la route','Klaxonner pour que les piétons quittent la chaussée'],answers:[0],explanation:'La zone de rencontre est un espace partagé avec des règles particulières donnant une place importante aux piétons. Adapte ton allure et respecte la signalisation.',rule:'Zones de rencontre et partage de l’espace public.',difficulty:'Moyen',source:'Pédagogie originale'},
  {id:'q195',theme:'divers',prompt:'Tu tractes une remorque et constates que ses feux ne fonctionnent pas. Que dois-tu faire ?',choices:['Partir si le trajet est court','Faire réparer ou rétablir la signalisation avant de circuler','Allumer les feux de détresse de la voiture en permanence'],answers:[1],explanation:'La remorque doit être correctement attelée et sa signalisation doit fonctionner. Ne circule pas dans une situation qui rend le véhicule non conforme ou dangereux.',rule:'Sécurité et signalisation des remorques.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q196',theme:'divers',prompt:'Un objet dépasse de ton chargement et pourrait tomber sur la chaussée. Quelle est ta priorité ?',choices:['L’arrimer correctement et respecter les règles de dimensions et de signalisation','Continuer si tu roules lentement','Demander à un passager de le tenir par la fenêtre'],answers:[0],explanation:'Le chargement doit être stable, arrimé et ne pas créer de danger. Les dépassements de dimensions sont soumis à des règles particulières.',rule:'Transport et arrimage des chargements.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q197',theme:'divers',prompt:'Après un accident matériel sans blessé, quelle attitude adopter avant de remplir le constat ?',choices:['Mettre les personnes et les véhicules en sécurité lorsque cela est possible','Laisser les véhicules au milieu d’une voie dangereuse pour discuter','Prendre des photos en restant sur une voie rapide'],answers:[0],explanation:'La sécurité prime sur les formalités. Protège les personnes, évite le suraccident et alerte les secours si un danger ou une blessure est constaté.',rule:'Sécurisation des lieux après un accident.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q198',theme:'divers',prompt:'Tu souhaites stationner quelques minutes sur une piste cyclable pour livrer un objet. Est-ce autorisé ?',choices:['Oui si les feux de détresse sont allumés','Non, les feux de détresse ne rendent pas le stationnement autorisé','Oui si tu restes dans le véhicule'],answers:[1],explanation:'Les feux de détresse ne rendent pas licite un arrêt ou stationnement interdit. Ne bloque pas une piste cyclable.',rule:'Arrêt et stationnement gênants ou interdits.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q199',theme:'divers',prompt:'Un passager ouvre sa portière alors qu’un vélo arrive. Quelle mesure préventive aurait permis d’éviter ce danger ?',choices:['Contrôler l’arrivée des usagers avant d’ouvrir et ouvrir progressivement','Ouvrir la portière d’un seul geste','Se fier uniquement au rétroviseur intérieur'],answers:[0],explanation:'Le contrôle du rétroviseur et de l’angle mort, puis une ouverture progressive, permettent de mieux détecter les cyclistes et deux-roues.',rule:'Ouverture des portières et prévention des collisions.',difficulty:'Facile',source:'Pédagogie originale'},
  {id:'q200',theme:'divers',prompt:'Tu arrives sur une route où les indications d’un agent de circulation semblent contredire un panneau. Que dois-tu suivre ?',choices:['Le panneau','Les indications de l’agent','La règle la plus rapide'],answers:[1],explanation:'Les prescriptions d’un agent chargé de régler la circulation priment sur les feux, panneaux et règles générales.',rule:'Hiérarchie des prescriptions de circulation.',difficulty:'Facile',source:'Pédagogie originale'}
];
